import{_ as e,c as n,o as t,ae as s}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"MODERNIZING DEFENSE ACQUISITIONS AND SPURRING INNOVATION IN THE DEFENSE INDUSTRIAL BASE","description":"","frontmatter":{"title":"MODERNIZING DEFENSE ACQUISITIONS AND SPURRING INNOVATION IN THE DEFENSE INDUSTRIAL BASE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base/","publishDate":"2025-04-09T19:20:05-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-09-modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base.md","filePath":"executive-orders/2025-04-09-modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base.md"}'),o={name:"executive-orders/2025-04-09-modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base.md"};function a(r,i,l,u,d,c){return t(),n("div",null,i[0]||(i[0]=[s('<h1 id="modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base" tabindex="-1">MODERNIZING DEFENSE ACQUISITIONS AND SPURRING INNOVATION IN THE DEFENSE INDUSTRIAL BASE <a class="header-anchor" href="#modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base" aria-label="Permalink to &quot;MODERNIZING DEFENSE ACQUISITIONS AND SPURRING INNOVATION IN THE DEFENSE INDUSTRIAL BASE&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/modernizing-defense-acquisitions-and-spurring-innovation-in-the-defense-industrial-base/</a></p><p>Published: 2025-04-09T19:20:05-04:00</p><ul><li>The President emphasizes the importance of the U.S. military&#39;s capabilities and the defense industrial base in maintaining military strength.</li><li>Acknowledges that the current defense acquisition system is outdated, lacking the necessary speed and flexibility needed for future military advantages.</li><li>The objective is to modernize defense procurement and revitalizing the industrial base for enhanced national security through: <ul><li>Accelerated and streamlined defense acquisitions.</li><li>A revamped defense acquisition workforce promoting innovation and risk-taking.</li></ul></li></ul><p><strong>Key Directives:</strong></p><ul><li><p><strong>Within 60 Days:</strong></p><ul><li>Secretary of Defense to submit a reform plan for acquisition processes prioritizing: <ul><li>Use of expedited authorities for acquisitions (e.g., commercial solutions and Other Transactions Authority).</li><li>Review to eliminate unnecessary tasks and centralize decision-making in the acquisition workforce.</li><li>Establishment of a Configuration Steering Board to manage acquisition program risks.</li></ul></li></ul></li><li><p><strong>Review Acquisition Regulations:</strong></p><ul><li>Revise unnecessary internal guidance and regulations while promoting expedited processes.</li><li>Apply the &quot;ten-for-one&quot; rule for any new regulations.</li></ul></li><li><p><strong>Within 120 Days:</strong></p><ul><li>Develop a plan to reform and train the acquisition workforce focusing on: <ul><li>New performance metrics incorporating commercial solutions.</li><li>Analysis of staffing needs for effective capability delivery.</li><li>Creation of field training teams for innovative acquisition practices.</li><li>Incentivization of the use of innovative acquisition authorities.</li></ul></li></ul></li><li><p><strong>Comprehensive Reviews:</strong></p><ul><li>Within 90 Days: Complete a review of all major defense acquisition programs (MDAPs) to identify those not aligning with policy objectives, considering potential cancellations for underperforming programs.</li><li>Within 180 Days: Review the Joint Capabilities Integration and Development System to streamline and accelerate acquisition processes.</li></ul></li></ul><p><strong>Definitions:</strong></p><ul><li>Clarifies key terms related to acquisition processes, such as: <ul><li>Adaptive Acquisition Framework and acquisition program baselines.</li><li>Commercial solutions and innovative acquisition authorities.</li></ul></li></ul><p><strong>Implementation Notes:</strong></p><ul><li>The order does not affect established executive authorities or OMB functions.</li><li>Actions should be consistent with applicable law and contingent on appropriations.</li><li>No new enforceable rights are created through this order.</li></ul>',10)]))}const g=e(o,[["render",a]]);export{f as __pageData,g as default};
